<h2 class="text-headline-md font-semibold">Pagos de <?= e($state['anio']) ?></h2>
<div class="renta-sheet-scroll"><table class="renta-sheet-table"><thead><tr><th>Mes del pago</th><th>Capital</th><th>Intereses</th><th>Seguros</th><th>Mora y otros</th><th>Total pagado</th><th>Cruce con libranza</th></tr></thead><tbody>
<?php $sums=array_fill_keys(['capital','intereses','seguros','otros','pago'],0);$has=false;foreach ($calendar as $month=>$c): $has=$has||$c['pago']!==null;foreach ($sums as $key=>$_) { $sums[$key]+=$c[$key]??0; } ?>
<tr><th><?= e(\App\Services\ExtractoData::MONTHS[$month]) ?></th><?php foreach (array_keys($sums) as $key): ?><td><?= e($money($c[$key])) ?></td><?php endforeach; ?><td><?= $c['pago']===null?'Falta extracto del crédito':($c['libranza']===null?'Pendiente Colpensiones':(abs($c['pago']-$c['libranza'])<=1?'Importes coinciden; confirmar crédito':'Revisar diferencia '.e($money(abs($c['pago']-$c['libranza']))))) ?></td></tr>
<?php endforeach; ?></tbody><tfoot><tr><th>Acumulado registrado</th><?php foreach ($sums as $sum): ?><td><?= $has?e($money($sum)):'—' ?></td><?php endforeach; ?><td>Parcial si faltan meses</td></tr></tfoot></table></div>
<details><summary class="text-secondary underline">Cruce mensual de Colpensiones con el banco</summary><div class="renta-sheet-scroll"><table class="renta-sheet-table"><thead><tr><th>Mes</th><th>Neto del comprobante</th><th>Pensión recibida en bancos</th><th>Resultado</th></tr></thead><tbody>
<?php foreach ($calendar as $month=>$c): if ($c['neto']===null && $c['banco']===null) { continue; } ?><tr><th><?= e(\App\Services\ExtractoData::MONTHS[$month]) ?></th><td><?= e($money($c['neto'])) ?></td><td><?= e($money($c['banco'])) ?></td><td><?= $c['neto']===null?'Falta comprobante de Colpensiones':($c['banco']===null?'Falta extracto bancario':(abs($c['neto']-$c['banco'])<=1?'Coinciden':'Diferencia '.e($money(abs($c['neto']-$c['banco']))))) ?></td></tr><?php endforeach; ?>
</tbody></table></div></details>
